    if isinstance(name_node, ast.Attribute):
        obj_fq = _resolve_name(name_node.value, aliases)
        if obj_fq is None:
            return None
        return f"{obj_fq}.{name_node.attr}"
    elif isinstance(name_node, ast.Name):
        return aliases.get(name_node.id)
    return None


