    return None


def has_star_import(tree: ast.Module) -> bool:
    """Return True if the module contains any ``from x import *`` statement."""
    for node in ast.walk(tree):
        if isinstance(node, ast.ImportFrom):
            if any(a.name == "*" for a in node.names):
